// AddForm.vue — 逻辑
import { ref, defineEmits } from 'vue'
const emit = defineEmits(['add'])
const name = ref('')
const composer = ref('')
const image = ref('')
const period = ref('')
const errorMsg = ref('')
function handleSubmit() {
  errorMsg.value = ''
  if (!name.value.trim() || !composer.value.trim()) {
    errorMsg.value = '请至少填写曲名和作曲家'
    return
  }
  emit('add', {
    name: name.value.trim(),
    composer: composer.value.trim(),
    image: image.value.trim() || '',
    period: period.value || '未分类'
  })
  // 清空表单
  name.value = ''
  composer.value = ''
  image.value = ''
  period.value = ''
}

steps.content:
现在来到最关键的一步——在 App.vue 中把所有组件组装起来，让它们协同工作。
App.vue 扮演"指挥"的角色：
1. **拥有所有数据**——`pieces` 数组（ref）和 `selectedPeriod` 状态（ref）
2. **用 computed 做筛选**——根据 `selectedPeriod` 从 `pieces` 中筛出要显示的曲目
3. **用 v-for 渲染卡片**——遍历筛选结果，给每个 MusicCard 传 props
4. **处理子组件的事件**——`@add`、`@toggle-like`、`@delete`
关键代码结构：
```vue
<script setup>
import { ref, computed } from 'vue'
import MusicCard from './components/MusicCard.vue'
import FilterBar from './components/FilterBar.vue'
import AddForm from './components/AddForm.vue'
const pieces = ref([
  { id: 1, name: 'G大调第一无伴奏大提琴组曲', composer: '巴赫', ... },
  // ... 更多初始数据
])
const selectedPeriod = ref('全部')
const periods = computed(() => {
  const set = new Set(pieces.value.map(p => p.period))
  return ['全部', ...set]
})
const filteredPieces = computed(() => {
  if (selectedPeriod.value === '全部') return pieces.value
  return pieces.value.filter(p => p.period === selectedPeriod.value)
})
function addPiece(data) { ... }
function toggleLike(id) { ... }
function deletePiece(id) { ... }
</script>
```注意 `periods` 这个 computed：它从 pieces 中**自动提取**所有不重复的时期——以后添加了新时期的曲目，筛选按钮会自动出现。这就是"数据驱动"的威力。

