// App.vue — 逻辑
import { ref, computed } from 'vue'
import MusicCard from './components/MusicCard.vue'
import FilterBar from './components/FilterBar.vue'
import AddForm from './components/AddForm.vue'
let nextId = 4
const pieces = ref([
  {
    id: 1,
    name: 'G大调第一无伴奏大提琴组曲',
    composer: '巴赫',
    image: 'https://upload.wikimedia.org/wikipedia/commons/6/6a/Johann_Sebastian_Bach.jpg',
    period: '巴洛克',
    liked: false
  },
  {
    id: 2,
    name: 'g小调第40号交响曲',
    composer: '莫扎特',
    image: 'https://upload.wikimedia.org/wikipedia/commons/1/1e/Wolfgang-amadeus-mozart_1.jpg',
    period: '古典',
    liked: true
  },
  {
    id: 3,
    name: '月光',
    composer: '德彪西',
    image: 'https://upload.wikimedia.org/wikipedia/commons/8/87/Claude_Debussy_1905.png',
    period: '印象派',
    liked: false
  }
])
const selectedPeriod = ref('全部')
const periods = computed(() => {
  const set = new Set(pieces.value.map(p => p.period))
  return ['全部', ...set]
})
const filteredPieces = computed(() => {
  if (selectedPeriod.value === '全部') return pieces.value
  return pieces.value.filter(p => p.period === selectedPeriod.value)
})
function addPiece(data) {
  pieces.value.push({
    id: nextId++,
    name: data.name,
    composer: data.composer,
    image: data.image,
    period: data.period,
    liked: false
  })
}
function toggleLike(id) {
  const p = pieces.value.find(p => p.id === id)
  if (p) p.liked = !p.liked
}
function deletePiece(id) {
  pieces.value = pieces.value.filter(p => p.id !== id)
}

